// Interface sketch only: not imported by the current relay, not deployable.
// Voter must be generated by the exact matching wasm-bindgen CLI after build.
// SQL schema/restore, authenticated transports and control FSM are deliberately
// host injections. They must not be replaced by client-supplied callbacks.
export async function handlePeer(core, authenticatedMessage, host) {
  // Caller holds a single serialized event queue through every await below.
  // On any error discard core and restore from durable SQL before another event.
  core.step(authenticatedMessage);
  const batch = JSON.parse(core.ready());
  if (batch === null) return;
  host.storage.transactionSync(() => {
    host.persistRaftBatch(batch); // snapshot + log suffix + HardState, atomic
  });
  await host.storage.sync(); // no peer response or advance before this resolves
  const applied = JSON.parse(core.persisted(BigInt(batch.sequence)));
  if (applied.committed.length) {
    const index = host.lastEntryIndex(applied.committed);
    host.storage.transactionSync(() => {
      // State, original-operation receipt and applied index in one transaction.
      host.applyCommittedAndSaveIndex(applied.committed, index);
    });
    await host.storage.sync();
    core.applied(BigInt(index));
  }
  // Conservative: even Raft messages allowed before apply wait for both barriers.
  await host.sendAuthenticated(applied.messages);
}
